import sqlite3

def query_db(sql, params=None):
    try:
        conn = sqlite3.connect('app.db')
        cur = conn.cursor()
        if params:
            cur.execute(sql, params)
        else:
            cur.execute(sql)
        result = cur.fetchall()
        conn.close()
        return result
    except sqlite3.Error as e:
        print('Database error:', e)
        return None

def fetch_users():
    return query_db('SELECT id, email FROM users')

def fetch_orders():
    return query_db('SELECT id, user_id FROM orders')

def main():
    users = fetch_users()
    orders = fetch_orders()
    print('Users:', users)
    print('Orders:', orders)

main()

