def list_by_category(inventory, category):
    return [row for row in inventory if row.get('category') == category]

def total_value_per_category(inventory):
    totals = {}
    for row in inventory:
        cat = row.get('category')
        val = row.get('quantity', 0) * row.get('price', 0)
        totals[cat] = totals.get(cat, 0) + val
    return totals

def low_stock_items(inventory):
    return [row for row in inventory if row.get('quantity', 0) < 10]

def inventory_summary(inventory):
    category = list_by_category(inventory, 'Electronics')
    value = total_value_per_category(inventory)
    low = low_stock_items(inventory)
    return {'category_products': category, 'total_value_by_category': value, 'low_stock': low}

