def merge_tables(table_a, table_b, on_key):
    b_by_key = {}
    for row in table_b:
        key = row.get(on_key)
        if key is not None:
            b_by_key.setdefault(key, []).append(row)
    result = []
    for row_a in table_a:
        key = row_a.get(on_key)
        if key in b_by_key:
            for row_b in b_by_key[key]:
                combined = {}
                for k, v in row_a.items():
                    combined[f'a_{k}'] = v
                for k, v in row_b.items():
                    combined[f'b_{k}'] = v
                result.append(combined)
    return result

